  const EDGE_LABELS: { text: string; width: number; height: number; placement: string | null }[][] = [[]]
  const DIMS: [number, number][] = [[60,30]]
  const NAMES: string[] = ["n1"]
  const PORT_IDS: string[] = []
  const PORT_CONSTRAINTS: (string | null)[] = ["FIXED_ORDER"]
