      const e = createSimpleEdge(nodeOf.get(s)!, nodeOf.get(t)!, sp, tp, __srcMerge, __tgtMerge)
      e.setProperty(MODEL_ORDER_KEY, ei)
      if (EDGE_YO[ei]) e.setProperty(INSIDE_SELF_LOOPS_YO_KEY, true)
