  const EDGE_LABELS: { text: string; width: number; height: number; placement: string | null }[][] = [[{"text":"center","width":43,"height":21,"placement":"CENTER"},{"text":"begin","width":39,"height":21,"placement":"TAIL"},{"text":"end","width":26,"height":21,"placement":"HEAD"}]]
